//! 📇️ Captured source bytes cover a complete mapped grapheme before any font layout is published.
use super::{super::{AdmittedFont,FontSource,FontFace,FontOutlineLimits,FontProgress},unicode::{UnicodeLayout,UnicodeProperty,normalize::NormalizedScalar,cluster::UnicodeCluster}};
use semio_framework_value::{list::PagedList,retirement::{RetireOwned,RetirementCursor}};
#[path="🧵️scalar/🦀️.rs"]
pub mod scalar;
use scalar::FontCanonicalScalarCursor;
#[derive(Clone,Copy,Debug)]
pub struct FontMappedScalar{pub glyph:u16,pub scalar:u32,pub source_at:usize,pub property:UnicodeProperty}
semio_framework_value::artifact_retire_leaf!(FontMappedScalar);
#[derive(semio_framework_value::RetireOwned)]
pub struct FontClusterMapping{pub face:usize,pub glyphs:Vec<FontMappedScalar>}
#[derive(semio_framework_value::RetireOwned)]
struct Owners{scalar_job:Option<FontCanonicalScalarCursor>,scalar_output:Option<Vec<FontMappedScalar>>,retained_scalars:PagedList<FontCanonicalScalarCursor,{usize::MAX}>,retained_outputs:PagedList<Vec<FontMappedScalar>,{usize::MAX}>,output:Option<FontClusterMapping>,failure:Option<String>}
pub struct FontClusterFaceCursor{owners:Owners,layout:UnicodeLayout,data_pointer:usize,source_pointer:usize,source_count:usize,faces:[Option<FontFace>;32],font_pointers:[usize;32],font_count:usize,cluster:UnicodeCluster,face_at:usize,map_at:usize,limits:FontOutlineLimits,phase:u8,work:u64,cancelled:bool,copy_at:usize}
impl RetireOwned for FontClusterFaceCursor{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
impl FontClusterFaceCursor{
 pub fn new<S:FontSource>(layout:UnicodeLayout,bytes:&[u8],source:&PagedList<NormalizedScalar,{usize::MAX}>,fonts:&[AdmittedFont<S>],cluster:UnicodeCluster,start_face:usize,limits:FontOutlineLimits)->Self{let mut faces=[None;32];let mut font_pointers=[0;32];for(index,font)in fonts.iter().take(32).enumerate(){faces[index]=Some(font.face);font_pointers[index]=font.source.as_ref().as_ptr()as usize;}let invalid=bytes.len()!=layout.byte_length||fonts.is_empty()||fonts.len()>32||start_face>=fonts.len()||cluster.start>=cluster.end||cluster.end>source.len()||cluster.end-cluster.start>limits.max_glyphs;Self{owners:Owners{scalar_job:None,scalar_output:None,retained_scalars:PagedList::new(),retained_outputs:PagedList::new(),output:Some(FontClusterMapping{face:start_face,glyphs:Vec::new()}),failure:invalid.then(||"Invalid original font cluster authority".into())},layout,data_pointer:bytes.as_ptr()as usize,source_pointer:source.get(0).map_or(0,|value|value as*const NormalizedScalar as usize),source_count:source.len(),faces,font_pointers,font_count:fonts.len(),cluster,face_at:start_face,map_at:0,limits,phase:3,work:0,cancelled:false,copy_at:0}}
 fn step<S:FontSource>(&mut self,bytes:&[u8],source:&PagedList<NormalizedScalar,{usize::MAX}>,fonts:&[AdmittedFont<S>])->Result<(),String>{if bytes.len()!=self.layout.byte_length||bytes.as_ptr()as usize!=self.data_pointer||source.len()!=self.source_count||source.get(0).map_or(0,|value|value as*const NormalizedScalar as usize)!=self.source_pointer||fonts.len()!=self.font_count{return Err("Captured font cluster source changed".into());}match self.phase{3=>{let count=(self.cluster.end-self.cluster.start).saturating_mul(64).min(self.limits.max_glyphs);self.owners.output.as_mut().unwrap().glyphs.try_reserve_exact(count).map_err(|_|"Font cluster glyph admission refused")?;self.phase=4;},4=>{if self.face_at==fonts.len(){return Err("Unicode grapheme has no single admitted font source".into());}let font=&fonts[self.face_at];if font.source.as_ref().as_ptr()as usize!=self.font_pointers[self.face_at]||font.source.as_ref().len()!=self.faces[self.face_at].unwrap().byte_length{return Err("Original font cluster source changed".into());}self.owners.output.as_mut().unwrap().face=self.face_at;self.map_at=0;self.phase=5;},5=>{if self.map_at==self.cluster.end-self.cluster.start{self.phase=7;return Ok(());}self.owners.scalar_job=Some(FontCanonicalScalarCursor::new(self.faces[self.face_at].unwrap(),fonts[self.face_at].source.as_ref(),self.layout,bytes,*source.get(self.cluster.start+self.map_at).unwrap(),self.limits.max_work));self.phase=6;},6=>{let font=&fonts[self.face_at];if font.source.as_ref().as_ptr()as usize!=self.font_pointers[self.face_at]{return Err("Original font cluster source changed".into());}if !self.owners.scalar_job.as_mut().unwrap().advance(font.source.as_ref(),bytes,1)?.done{return Ok(());}if !super::super::reserve_slot(&mut self.owners.retained_scalars)?{return Ok(());}let output=self.owners.scalar_job.as_mut().unwrap().take_result()?;self.owners.retained_scalars.push_reserved(self.owners.scalar_job.take().unwrap()).map_err(|_|"Canonical font child reservation lost")?;if let Some(output)=output{self.owners.scalar_output=Some(output);self.copy_at=0;self.phase=8;}else{self.owners.output.as_mut().unwrap().glyphs.clear();self.face_at+=1;self.phase=4;}},8=>{let original=self.owners.scalar_output.as_ref().unwrap();if self.copy_at==original.len(){if !super::super::reserve_slot(&mut self.owners.retained_outputs)?{return Ok(());}self.owners.retained_outputs.push_reserved(self.owners.scalar_output.take().unwrap()).map_err(|_|"Canonical font output reservation lost")?;self.map_at+=1;self.phase=5;return Ok(());}let output=self.owners.output.as_mut().unwrap();if output.glyphs.len()==self.limits.max_glyphs{return Err("Font cluster glyph limit exceeded".into());}output.glyphs.push(original[self.copy_at]);self.copy_at+=1;},_=>return Err("Original font cluster stage invalid".into())}Ok(())}
 pub fn advance<S:FontSource>(&mut self,bytes:&[u8],source:&PagedList<NormalizedScalar,{usize::MAX}>,fonts:&[AdmittedFont<S>],grant:usize)->Result<FontProgress,String>{if grant==0{return Err("Invalid font cluster work grant".into());}if self.cancelled{return Err("Original font cluster cancelled".into());}if let Some(error)=&self.owners.failure{return Err(error.clone());}for _ in 0..grant{if self.phase==7{break;}if self.work==self.limits.max_work{self.owners.failure=Some("Font cluster work limit exceeded".into());return Err(self.owners.failure.as_ref().unwrap().clone());}if let Err(error)=self.step(bytes,source,fonts){self.owners.failure=Some(error.clone());return Err(error);}self.work+=1;}Ok(FontProgress{phase:match self.phase{3=>"glyphAdmission",4=>"font",5=>"scalar",6=>"cmap",8=>"copy",_=>"complete"},work:self.work,done:self.phase==7})}
 pub fn result(&self)->Result<&FontClusterMapping,String>{if self.phase!=7||self.cancelled||self.owners.failure.is_some(){return Err("Original font cluster incomplete".into());}self.owners.output.as_ref().ok_or_else(||"Original font cluster output transferred".into())}
 pub fn take_result(&mut self)->Result<FontClusterMapping,String>{self.result()?;Ok(self.owners.output.take().unwrap())}
 pub fn cancel(&mut self){self.cancelled=true;}
}
